import {esc,conversation,request} from './customer-shared.mjs';
export function mountSupport(root,s,{backend,onSelect}){
 if(!s){if(!backend)return;const box=document.createElement('section');box.className='support-inbox';root.prepend(box);request('/api/support/inbox').then(d=>{if(!box.isConnected)return;if(!d.items.length){box.remove();return;}box.innerHTML=`<span class="eyebrow">CUSTOMER FOLLOW-UPS</span><h2>${d.items.length} conversation${d.items.length===1?' needs':'s need'} your attention.</h2><p>A verified access check does not replace the customer’s experience.</p><div class="support-actions">${d.items.map((item,i)=>`<button class="button" data-support-case="${i}"><strong>${esc(item.customerName)}</strong> · ${esc(item.text)} ↗</button>`).join('')}</div>`;box.querySelectorAll('button').forEach(b=>b.onclick=()=>onSelect(d.items[Number(b.dataset.supportCase)].caseId));}).catch(()=>{box.textContent='Customer follow-ups could not be checked. Refresh records to retry.';});return;}const target=root.querySelector('.case-evidence-column');if(!target)return;
 const panel=document.createElement('section');panel.className='support-panel';target.prepend(panel);
 if(!backend){panel.innerHTML='<h2>Customer communication</h2><p>Messaging and private customer links require the server-backed app.</p>';return;}
 let pending=null,busy=false;
 async function api(body){return request('/api/support'+(body?'':'?caseId='+encodeURIComponent(s.id)),body?{...body,caseId:s.id}:undefined);}
 function show(d){panel.innerHTML=`<span class="eyebrow">CUSTOMER COMMUNICATION</span><h2>Keep ${esc(s.customerName)} in the loop.</h2><p class="subtle">Customer-visible replies stay separate from the investigation. Only an unlocked operator can send messages or share access. <a href="recover.html#desk">Open operator setup ↗</a></p>${d.help?'<div class="support-attention">Customer needs more help. Technical verification alone has not resolved their concern.</div>':''}${d.request?`<div class="support-attention"><strong>Waiting for the customer</strong><p>${esc(d.request)}</p></div>`:''}<p class="subtle">Customer confirmation: ${d.confirmedAt&&d.verified?'Received':'Not yet received'}</p><div class="customer-thread">${conversation(d.messages)}</div><form id="support-reply"><label for="support-kind">Message visibility</label><select id="support-kind"><option value="message">Reply to customer · human</option><option value="request">Request information · customer action needed</option><option value="internal">Private admin note · hidden from customer</option><option value="ai-draft">AI-assisted reply · reviewed by merchant</option></select><label for="support-text">Your message</label><textarea id="support-text" required maxlength="2000" placeholder="Explain the next step, or ask a specific question.">${esc(pending?.text||'')}</textarea><small>Never request passwords or full payment details. AI-assisted replies must be reviewed before sending.</small><div class="support-actions"><button class="button primary" type="submit">Save message</button><button class="button" type="button" id="support-refresh">Refresh conversation</button></div></form><details><summary>Customer link & email updates</summary><p>Register an email only after matching it to the purchase. Anyone with a private link can read this case and reply.</p><form id="support-contact"><label for="support-email">Verified purchase email</label><input id="support-email" type="email" required maxlength="254" value="${esc(d.email)}"><label class="support-check"><input type="checkbox" required> I matched this email to the purchase record.</label><button class="button" type="submit">Save purchase email</button></form><div class="support-actions"><button class="button" id="support-invite">Email private link</button><button class="button" id="support-link">Create private preview link</button><button class="button" id="support-revoke">Revoke customer links</button></div><div id="support-link-result"></div><p class="subtle">Links expire in 24 hours and can be opened once. Revoking also ends existing customer sessions.</p><h3>Email activity</h3><p class="subtle">Provider acceptance does not confirm inbox delivery. Unconfigured or failed emails are not automatically retried; send a fresh invitation after fixing setup.</p><ul>${d.notifications.slice(-5).map(n=>`<li>${esc(n.state)} · ${esc(new Date(n.at).toLocaleString())}</li>`).join('')||'<li>No email attempts yet.</li>'}</ul></details><p class="support-feedback" role="status"></p>`;
 const feedback=()=>panel.querySelector('.support-feedback');
 async function perform(body,after){if(busy)return;busy=true;panel.querySelectorAll('button').forEach(b=>b.disabled=true);try{const result=await api(body);if(after)after(result);else{pending=null;show(await api());panel.querySelector('.support-feedback').textContent=body.action==='internal'?'Private note saved.':body.action==='contact'?'Email saved.':body.action==='revoke'?'Customer access links revoked.':'Saved to the customer conversation. Email activity shows notification status.';}}catch(e){if(e.rejected)pending=null;feedback().textContent=e.message+(pending?' Retry will send the original message once.':'');panel.querySelector('#support-text').disabled=!!pending;panel.querySelector('#support-kind').disabled=!!pending;}finally{busy=false;panel.querySelectorAll('button').forEach(b=>b.disabled=false);}}
 panel.querySelector('#support-reply').onsubmit=e=>{e.preventDefault();pending||={action:panel.querySelector('#support-kind').value,text:panel.querySelector('#support-text').value,requestId:crypto.randomUUID()};perform(pending);};
 panel.querySelector('#support-kind').onchange=e=>{panel.querySelector('#support-reply button').textContent=e.target.value==='internal'?'Save private note':e.target.value==='request'?'Request information':'Send to customer';};
 panel.querySelector('#support-refresh').onclick=async()=>{const draft=panel.querySelector('#support-text').value;const kind=panel.querySelector('#support-kind').value;try{show(await api());panel.querySelector('#support-text').value=draft;panel.querySelector('#support-kind').value=kind;}catch(e){feedback().textContent=e.message;}};
 panel.querySelector('#support-contact').onsubmit=e=>{e.preventDefault();perform({action:'contact',email:panel.querySelector('#support-email').value});};
 panel.querySelector('#support-link').onclick=()=>perform({action:'link'},r=>{const box=panel.querySelector('#support-link-result');box.textContent='Private link — share only with the verified purchaser: ';const a=document.createElement('a');a.href=r.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=r.url;a.className='private-link';box.append(a);});
 panel.querySelector('#support-invite').onclick=()=>perform({action:'invite'},r=>feedback().textContent=r.message);
 panel.querySelector('#support-revoke').onclick=()=>perform({action:'revoke'});
 }
 panel.innerHTML='<p role="status">Loading customer conversation…</p>';api().then(d=>{if(panel.isConnected)show(d);}).catch(e=>{panel.textContent='Customer conversation unavailable. '+e.message;const b=document.createElement('button');b.className='button';b.textContent='Retry conversation';b.onclick=()=>api().then(show).catch(e=>panel.firstChild.textContent=e.message);panel.append(b);});
}
